/*
 * A069660  Order of the subgroup of the symmetric group S_n generated by the
 *          cycles (1,3) and (1,2,3,...,n).
 * https://oeis.org/A069660
 *
 * Offset:    3    (a(3) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = n! if n is odd a(n) = 2 * ((n/2)!)^2 (integer mult) if n
 *            is even
 * Range:     u8 n <= 6, u16 n <= 8, u32 n <= 12, u64 n <= 20, u128 n <= 24,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This implementation caches factorials to support n up to 10 000.
   For n >= 3 as requested, a(n) is returned exactly for any
   seq_t capable of arbitrary precision, or fits into the underlying
   integer type. */

#include <stdlib.h>
#include <stdint.h>

/* External integer types provided by the build system */
  /* idx_t  – for indices (unsigned 64‑bit)   */
  /* seq_t – the sequence value type (8/16/32/64/128‑bit or a big‑int class) */

/* Cache of factorials */
static seq_t* fact = NULL;      /* array of factorials fact[i] = i! */
static size_t fact_len = 0;     /* allocated length of fact array   */
static idx_t max_fact = 0;      /* maximum n for which fact[n] is valid */

/* Ensure factorials up to m are computed and cached */
static void ensure_factorial(idx_t m)
{
    if (m <= max_fact) return;            /* already computed */

    /* expand allocation if necessary */
    size_t needed = (size_t)(m + 1);
    if (fact_len == 0) {
        fact_len = 16;                    /* initial capacity        */
        fact = (seq_t*)malloc(fact_len * sizeof(seq_t));
        if (!fact) return;                /* allocation failed        */
        fact[0] = (seq_t)1;               /* 0! = 1                   */
        max_fact = 0;
    }
    if (needed > fact_len) {
        size_t newlen = fact_len;
        while (newlen < needed) newlen <<= 1;   /* double size */
        seq_t* tmp = (seq_t*)realloc(fact, newlen * sizeof(seq_t));
        if (!tmp) return;                   /* handle error */
        fact = tmp;
        fact_len = newlen;
    }

    /* compute missing factorials */
    seq_t acc = fact[max_fact];
    for (idx_t i = max_fact + 1; i <= m; ++i) {
        acc = acc * (seq_t)i;      /* multiplication using seq_t */
        fact[(size_t)i] = acc;
    }
    max_fact = m;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    if (n < 3) return (seq_t)0;   /* undefined below offset; return 0 */

    /* factorial might be needed up to n or n/2 */
    if (n & 1) {
        ensure_factorial(n);
        return fact[(size_t)n];
    } else {
        idx_t half = n >> 1;
        ensure_factorial(half);
        seq_t hfact = fact[(size_t)half];
        return ((seq_t)2) * hfact * hfact;  /* 2*((n/2)!)^2 */
    }
}
